    bool valid(ID3D12GraphicsCommandList* list,std::uint64_t fence) const{if(!list||!fence||fence<counters.lastFence||fence<=timeline.p->GetCompletedValue()||(list->GetType()!=D3D12_COMMAND_LIST_TYPE_DIRECT&&list->GetType()!=D3D12_COMMAND_LIST_TYPE_COMPUTE))return false;Com<ID3D12Device> owner;return SUCCEEDED(list->GetDevice(IID_PPV_ARGS(owner.out())))&&owner.p==device.p;}
